/* REBOUND / Solana interface. SOL-denominated recovery ledger.
   Address-only wallet access. No signing or transaction-sending method is used. */
(() => {
'use strict';
const E=window.ReboundEngine,F=window.ReboundFixtures,$=s=>document.querySelector(s),$$=s=>Array.from(document.querySelectorAll(s));
const STORAGE='rebound.demo.sol.v2';
let state=F.create(),route='explore',tokenId='demo-rbd',filter='all',search='',sort='cap',tradeSide='buy',detailTab='overview';
let launchStep=1,launchDraft={name:'',symbol:'',description:'',website:'',twitter:'',telegram:'',currency:'SOL',taxBps:500,image:null};
let provider=null,connectedAddress=null,providerListeners=[],walletBusy=false;
try{const raw=localStorage.getItem(STORAGE);if(raw){const restored=E.parse(raw);if(restored.version===2&&Array.isArray(restored.tokens)&&restored.tokens.length<=100&&Number.isSafeInteger(restored.now)&&typeof restored.demoBalances?.SOL==='bigint'){for(const t of restored.tokens){E.assertAccounting(t.treasury);E.validateTax(t.taxBps);if(!F.assets[t.currency]||!Array.isArray(t.positions)||t.currency!=='SOL'||t.decimals!==9||typeof t.priceQ!=='bigint'||t.priceQ<=0n)throw Error('Invalid saved demo');}state=restored;}}}catch{state=F.create();}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(n,d=9,p=4)=>E.formatUnits(n,d,Math.min(p,d));
const money=v=>v>=1e6?'$'+(v/1e6).toFixed(2)+'M':v>=1e3?'$'+(v/1e3).toFixed(1)+'K':'$'+v.toFixed(0);
const unit=t=>10n**BigInt(t.decimals);
const currentToken=()=>state.tokens.find(t=>t.id===tokenId)||state.tokens[0];
const pos=t=>t.positions.find(p=>p.wallet==='demo-holder');
const reference=t=>F.reference(t,state.now);
function save(){try{localStorage.setItem(STORAGE,E.stringify(state));}catch{toast('Browser storage is unavailable or full. Your demo will last only for this session.',true);}}
function toast(text,error=false){const d=document.createElement('div');d.className='toast'+(error?' error':'');d.textContent=text;$('#toasts').append(d);setTimeout(()=>d.remove(),7000);}
function go(hash){if(location.hash==='#'+hash)render();else location.hash=hash;}
function totals(field){const out={SOL:0n};for(const t of state.tokens)out[t.currency]+=t.treasury[field];return out;}
function assetTotals(values,precision=3){return `${fmt(values.SOL,9,precision)} <span class="asset-unit">SOL</span>`;}
function icon(t,large=false){
 const paths={rebound:'<path d="M7 7v11a8 8 0 0 0 16 0V5m-5 5 5-5 5 5"/>',orbit:'<circle cx="16" cy="16" r="7"/><ellipse cx="16" cy="16" rx="14" ry="5" transform="rotate(-35 16 16)"/>',wind:'<path d="M4 11h15a4 4 0 1 0-4-4M4 16h21a4 4 0 1 1-4 4M4 22h8"/>',cat:'<path d="m7 15-1-9 8 5h5l7-5-1 10c4 13-21 14-18-1Z"/><path d="M11 18h1m8 0h1m-7 6 2-2 2 2"/>',drift:'<path d="m4 20 8-10 5 10 6-12 6 12M5 25h23"/>',nimble:'<path d="m18 3-11 17h10l-3 10 12-18H16l2-9Z"/>',mellow:'<circle cx="16" cy="16" r="12"/><path d="M10 13h1m10 0h1M10 19c4 5 8 5 12 0"/>',encore:'<path d="m6 7 12 9L6 25V7Zm13 0v18m7-18v18"/>'};
 const image=typeof t.image==='string'&&/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(t.image)?`<img class="image-token" alt="" src="${esc(t.image)}">`:`<svg viewBox="0 0 32 32" aria-hidden="true">${paths[t.art]||paths.rebound}</svg>`;
 return `<span class="token-icon ${['lime','lilac','blue','peach','mint','pink','yellow'].includes(t.tone)?t.tone:'lime'} ${large?'large':''}">${image}</span>`;
}
function spark(seed=0,down=false){let y=23;const points=[];for(let x=0;x<=100;x+=4){y=Math.max(3,Math.min(27,y-0.54+Math.sin(x*1.3+seed)*3.8));points.push(`${x},${down?30-y:y}`);}return `<svg class="sparkline ${down?'down':''}" viewBox="0 0 100 30" aria-label="Illustrative price history"><path d="M${points.join(' L')}"/></svg>`;}
function uiIcon(name){
 const shapes={
  compass:'<circle cx="12" cy="12" r="9"/><path d="m16 8-2.6 5.4L8 16l2.6-5.4L16 8Z"/>',
  plus:'<path d="M12 5v14M5 12h14"/>',
  wallet:'<path d="M19 7H5a2 2 0 0 1 0-4h13v4M5 7a2 2 0 0 1-2-2v13a2 2 0 0 0 2 2h16V7h-2Z"/><path d="M21 11h-6v5h6M17.5 13.5h.01"/>',
  chart:'<path d="M4 4v16h17M8 15v-4m5 4V7m5 8V4"/>',
  layers:'<path d="m12 3 10 5-10 5L2 8l10-5ZM3 12l9 5 9-5M3 16l9 5 9-5"/>',
  book:'<path d="M4 4h6a3 3 0 0 1 2 1 3 3 0 0 1 2-1h6v15h-6a3 3 0 0 0-2 1 3 3 0 0 0-2-1H4V4Zm8 1v15"/>',
  arrow:'<path d="M5 19 19 5M6 5h13v13"/>',
  arrowRight:'<path d="M4 12h16m-6-6 6 6-6 6"/>',
  search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',
  clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
  shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Z"/><path d="m8 12 3 3 5-6"/>',
  spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3Z"/>',
  dots:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',
  grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',
  people:'<circle cx="9" cy="8" r="3"/><path d="M3 20v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6m3 9v-3a6 6 0 0 0-2-4"/>',
  bolt:'<path d="m13 2-9 12h7l-1 8 10-13h-8l1-7Z"/>'
 };
 return `<svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${shapes[name]||shapes.arrow}</svg>`;
}
function art(){return `<div class="engine-visual"><div class="engine-top"><span><i class="status-dot"></i> NET FEE ALLOCATION</span><span>80 / 15 / 5</span></div><div class="engine-number"><span>80</span><small>%</small><div class="engine-orbit" aria-hidden="true"></div></div><div class="engine-caption">of net fees → holder recovery</div><div class="engine-bars" aria-label="Fee distribution: 80% holders, 15% operations, 5% buybacks"><i></i><i></i><i></i></div><div class="engine-bottom"><span><i></i><b>15%</b> Operations</span><span><i></i><b>5%</b> $RBD buybacks</span></div><div class="engine-foot">Recovery follows holding rules and available fees.</div></div>`;}

function feeBar(){return '<div class="fee-bar" aria-label="80 percent holders, 15 percent operations, 5 percent buybacks"><span></span><span></span><span></span></div><div class="fee-legend"><span><i></i>80% Holders</span><span><i></i>15% Operations</span><span><i></i>5% $RBD</span></div>';}
function metrics(){return `<div class="stats-row"><div class="stat"><div class="stat-top"><span class="label">Holder rewards paid</span>${uiIcon('wallet')}</div><strong>${assetTotals(totals('paid'))}</strong><span class="sub"><i class="mini-dot"></i> Completed demo payments</span></div><div class="stat"><div class="stat-top"><span class="label">Available in treasuries</span>${uiIcon('layers')}</div><strong>${assetTotals(totals('available'))}</strong><span class="sub">Excludes already-funded awards</span></div><div class="stat"><div class="stat-top"><span class="label">Tokens launched</span>${uiIcon('bolt')}</div><strong>${state.tokens.length.toString().padStart(2,'0')}<span class="asset-secondary">Separate token treasuries</span></strong><span class="sub">Local token launches</span></div><div class="stat"><div class="stat-top"><span class="label">Holder positions</span>${uiIcon('people')}</div><strong>${state.tokens.reduce((s,t)=>s+t.positions.length,0)}<span class="asset-secondary">Across all demo tokens</span></strong><span class="sub">Sample wallets, not real users</span></div></div>`;}
function marketRows(){let tokens=state.tokens.filter(t=>(filter==='all'||(filter==='platform'?t.id==='demo-rbd':t.id!=='demo-rbd'))&&(`${t.name} ${t.symbol} ${t.id}`.toLowerCase().includes(search.toLowerCase())));tokens.sort((a,b)=>sort==='new'?b.createdAt-a.createdAt:sort==='change'?b.change-a.change:(b.marketCap||0)-(a.marketCap||0));return tokens.length?tokens.map((t,i)=>`<tr data-token="${esc(t.id)}" tabindex="0" aria-label="Open ${esc(t.name)} demo token"><td><div class="token-info">${icon(t)}<div><div class="token-name">${esc(t.name)}</div><div class="token-sub">$${esc(t.symbol)} <span>·</span> ${esc(t.currency)} rewards <span class="tag-inline">${(t.taxBps/100).toFixed(t.taxBps%100?2:0)}% tax</span></div></div></td><td class="numeric">${money(t.marketCap||0)}</td><td class="col-change ${(t.change||0)>=0?'positive':'negative'}">${(t.change||0)>=0?'+':''}${(t.change||0).toFixed(2)}%</td><td class="numeric">${money(t.volume||0)}</td><td class="col-rewards numeric">${fmt(t.treasury.paid,t.decimals,4)} <span>${esc(t.currency)}</span></td><td class="chart-col">${spark(i*3,(t.change||0)<0)}</td><td class="row-arrow">↗</td></tr>`).join(''):'<tr><td colspan="7" class="empty">No tokens match your search.</td></tr>';}
function explore(){
 const spotlight=state.tokens.filter(t=>['demo-rbd','demo-orbit','demo-wind'].includes(t.id));
 return `<section class="hero"><div class="hero-copy"><div class="eyebrow"><span class="eyebrow-line"></span>SOLANA / TOKEN LAUNCHES</div><h1>Launch a token.<br><em>Reward holders.</em></h1><p>Explore tokens with fee-funded recovery.<br>Holder rewards are paid in SOL.</p><div class="hero-actions"><a href="#launch" class="btn">Launch a token ${uiIcon('arrowRight')}</a><a href="#docs" class="btn ghost">How it works ${uiIcon('arrow')}</a></div><div class="hero-fineprint">${uiIcon('shield')} 15-minute hold · Fee-funded recovery · SOL payouts</div></div>${art()}</section>${metrics()}
 <section class="spotlight-section" aria-label="Featured demo tokens"><div class="section-heading compact"><h2>${uiIcon('spark')} Featured tokens</h2><span class="micro-label">CURATED DEMO TOKENS</span></div><div class="spotlight-grid">${spotlight.map((t,i)=>`<a class="spotlight-card" href="#token/${esc(t.id)}"><div class="spotlight-top"><span class="spotlight-position">0${i+1} / ${['ECOSYSTEM TOKEN','COMMUNITY TOKEN','RECENT LAUNCH'][i]}</span>${uiIcon('arrow')}</div><div class="spotlight-identity">${icon(t)}<div><h3>${esc(t.name)}</h3><span>$${esc(t.symbol)} <span class="spotlight-currency">· ${esc(t.currency)} rewards</span></span></div><span class="spotlight-change positive">+${t.change.toFixed(2)}%</span></div><div class="spotlight-bottom"><div><span class="micro-label">MARKET CAP</span><strong>${money(t.marketCap||0)}</strong></div>${spark(i*3)}</div></a>`).join('')}</div></section>
 <section class="market-section"><div class="section-heading"><div class="market-heading"><h2>Explore tokens</h2><span class="count-badge">${state.tokens.length}</span></div><span class="demo-data-label"><i class="mini-dot"></i> Demo market data</span></div><div class="toolbar"><div class="tabs" aria-label="Token category"><button data-filter="all" class="${filter==='all'?'active':''}">All tokens</button><button data-filter="community" class="${filter==='community'?'active':''}">Community</button><button data-filter="platform" class="${filter==='platform'?'active':''}">$RBD</button></div><div class="toolbar-right"><label class="search">${uiIcon('search')}<input id="search" placeholder="Search tokens…" aria-label="Search tokens" value="${esc(search)}"><kbd>/</kbd></label><select id="sort" aria-label="Sort tokens"><option value="cap" ${sort==='cap'?'selected':''}>Market cap ↓</option><option value="change" ${sort==='change'?'selected':''}>24h change ↓</option><option value="new" ${sort==='new'?'selected':''}>Newest first</option></select></div></div><div class="table-container"><table class="token-table"><thead><tr><th>Token</th><th>Market cap ↓</th><th>24h change</th><th>24h volume</th><th>Rewards paid</th><th class="chart-col">Price trend</th><th></th></tr></thead><tbody id="market-rows">${marketRows()}</tbody></table></div><div class="table-note"><span>Illustrative prices and charts. Not live market data.</span><span>${state.tokens.length} demo tokens</span></div></section>
 <section class="feature-grid"><div class="feature-card"><div class="feature-icon">${uiIcon('layers')}</div><div><div class="eyebrow">FEE ALLOCATION</div><h3>Where trading fees go</h3><p>Net collected fees support holders, operations, and the $RBD buyback reserve.</p>${feeBar()}</div></div><div class="feature-card tinted"><div class="feature-icon">${uiIcon('shield')}</div><div><div class="eyebrow">HOLDER RECOVERY</div><h3>Recovery, paid in SOL</h3><p>Awards cover recognized losses, capped by the shortfall and available treasury funds.</p><a href="#token/demo-rbd" class="arrow-link">View recovery details ${uiIcon('arrowRight')}</a></div></div></section>`;
}
function liveNotice(){return connectedAddress?`<div class="live-notice">Connected wallet: ${esc(connectedAddress)} · Read-only connection. All balances and actions below belong to <b>demo-holder</b>, not this wallet.</div>`:'';}
function taxLabels(t){return `<div class="kv"><span>Creator tax · buy / sell</span><strong>${t.taxBps/100}%</strong></div><div class="kv"><span>Demo venue fee</span><strong>1%</strong></div><div class="kv"><span>Combined demo fee</span><strong>${(t.taxBps+100)/100}%</strong></div>`;}
function launchPreview(){const d=launchDraft;return `<aside class="card sticky"><div class="card-title"><h3>Token preview</h3><span class="tag neutral">PREVIEW</span></div>${icon({...d,tone:'lime',art:'rebound'},true)}<div class="preview-name">${esc(d.name||'Token name')}</div><div class="preview-sub">$${esc(d.symbol||'TOKEN')} · ${esc(d.currency)} rewards</div><div class="divider"></div>${taxLabels(d)}<div class="kv"><span>Reward policy</span><strong>Comeback · loss-rebate/v1</strong></div><div class="kv"><span>Minimum holding time</span><strong>15 minutes</strong></div>${feeBar()}<p class="muted" style="font-size:10px;margin-top:18px;line-height:1.8">The split applies to net received creator tax and creator-fee share, not the full trade volume. The upstream standard creator share is unverified and excluded from demo quotes.</p></aside>`;}
function launchPage(){let content='';if(launchStep===1)content=`<h3 style="margin-bottom:23px">Token details</h3><label class="upload"><input id="image-input" type="file" accept="image/png,image/jpeg,image/webp" class="hidden"><span class="upload-art">${launchDraft.image?`<img src="${esc(launchDraft.image)}" alt="Token artwork preview">`:'+'}</span><span class="upload-text"><b>${launchDraft.image?'Change artwork':'Add token artwork'}</b><small>PNG, JPG or WebP · cropped to a square · stored locally</small></span></label><div class="input-row"><label class="field"><span>Token name</span><input id="launch-name" data-draft="name" maxlength="32" placeholder="e.g. Second Wind" value="${esc(launchDraft.name)}" autocomplete="off"></label><label class="field"><span>Ticker</span><input id="launch-symbol" data-draft="symbol" maxlength="10" placeholder="e.g. WIND" value="${esc(launchDraft.symbol)}" autocomplete="off"></label></div><label class="field"><span>Description <small>optional</small></span><textarea id="launch-description" data-draft="description" maxlength="500" placeholder="Describe your token and community.">${esc(launchDraft.description)}</textarea></label><label class="field"><span>Website <small>optional</small></span><input type="url" data-draft="website" placeholder="https://your-community.com" value="${esc(launchDraft.website)}"></label><div class="input-row"><label class="field"><span>X / Twitter <small>optional</small></span><input type="url" data-draft="twitter" placeholder="https://x.com/yourtoken" value="${esc(launchDraft.twitter)}"></label><label class="field"><span>Telegram <small>optional</small></span><input type="url" data-draft="telegram" placeholder="https://t.me/yourtoken" value="${esc(launchDraft.telegram)}"></label></div>`;
else if(launchStep===2)content=`<h3 style="margin-bottom:22px">Fees and rewards</h3><label class="field"><span>Reward currency</span></label><div class="option-grid mb"><button data-currency="SOL" class="option ${launchDraft.currency==='SOL'?'active':''}"><h4>◎ SOL</h4><p>Native Solana asset</p></button></div><label class="field"><span>Creator tax <small>same on buys and sells</small></span><div class="input-row"><input id="tax-range" type="range" min="10" max="1000" step="1" value="${launchDraft.taxBps}" aria-label="Creator tax basis points"><input id="tax-number" type="number" min="0.1" max="10" step="0.01" value="${launchDraft.taxBps/100}" aria-label="Creator tax percent"></div><small>0.10%-10.00% · Fixed for this launch. Separate 1% demo venue fee.</small></label><div class="mode-card active"><div class="card-title" style="margin:0"><h4>↗ Comeback mode</h4><span class="tag lime">LOSS-REBATE/V1</span></div><p>Fees target holder shortfalls. Awards are weighted by remaining loss and stop at break-even.</p></div>`;
else content=`<h3 style="margin-bottom:22px">Review your token</h3><div class="notice warning mb">This creates a local demo token only. There is no mint, program deployment, wallet signature, fee payment, or real trading pool.</div><div class="kv"><span>Name / ticker</span><strong>${esc(launchDraft.name)} / ${esc(launchDraft.symbol)}</strong></div><div class="kv"><span>Trading & reward unit</span><strong>${esc(launchDraft.currency)}</strong></div><div class="kv"><span>Creator tax</span><strong>${launchDraft.taxBps/100}% · immutable in the demo</strong></div><div class="kv"><span>Token policy</span><strong>Comeback · loss-rebate/v1</strong></div><div class="kv"><span>Initial on-chain supply</span><strong>Not minted</strong></div><div class="divider"></div><div class="notice">Any sale or outgoing transfer permanently ends eligibility for future rounds. Already-funded awards remain claimable. Recovery depends on available fees and is not guaranteed.</div>`;
return `<div class="page-head"><div><div class="eyebrow">NEW TOKEN / SOLANA CONCEPT</div><h1>Create a token</h1><p>Set the token details and fee policy. Review before creating the demo.</p></div><span class="tag warning">LOCAL SIMULATION</span></div><div class="steps"><span class="${launchStep===1?'active':''}"><b>1</b>Identity</span><span class="${launchStep===2?'active':''}"><b>2</b>Mechanics</span><span class="${launchStep===3?'active':''}"><b>3</b>Review</span></div>${liveNotice()}<div class="two-columns"><section class="card">${content}<div id="launch-error" class="error" role="alert"></div><div class="form-actions"><button class="btn outline" data-action="launch-back">${launchStep===1?'← Explore':'← Back'}</button><button class="btn dark" data-action="launch-next">${launchStep===3?'Create demo token ↗':'Continue →'}</button></div></section>${launchPreview()}</div>`;}
function positionSummary(t,p,showAction=true){const s=E.shortfall(p,reference(t));const allCost=p.lots.reduce((s,l)=>s+l.cost,0n),quantity=p.lots.reduce((s,l)=>s+l.quantity,0n),value=quantity*t.priceQ/E.PRICE_SCALE;const pct=allCost>0n?Math.min(100,Number((value+p.paid)*10000n/allCost)/100):0,valuePct=allCost>0n?Math.min(100,Number(value*10000n/allCost)/100):0;const paidPct=Math.min(100-valuePct,allCost>0n?Number(p.paid*10000n/allCost)/100:0);const estimate=E.allocate(t.treasury.available,t.positions.map(p=>E.shortfall(p,reference(t)))).allocations.find(a=>a.wallet===p.wallet)?.amount||0n;const waiting=t.treasury.rounds.some(r=>!r.cancelled&&state.now<r.claimableAt);
return `<div class="card-title"><h3>Your ${esc(t.symbol)} recovery</h3><span class="tag ${s.eligible?'lime':s.reason==='outgoing'?'warning':'neutral'}">${s.reason==='outgoing'?'INELIGIBLE':s.eligible?'ELIGIBLE':s.reason==='holding-period'?'15 MIN HOLD':'COVERED'}</span></div><div class="recovery-value">${s.reason==='outgoing'?'-':pct.toFixed(1)+'%'}<small>${s.reason==='outgoing'?'recovery not comparable':'of entry covered'}</small></div><p class="muted" style="font-size:10px">Token value + completed payouts. Pending awards are not received funds.</p>${s.reason==='outgoing'?'<div class="notice danger mt">An outgoing transfer or sale ended future eligibility. Already-funded awards remain yours.</div>':`<div class="progress"><span style="width:${valuePct}%"></span><span class="paid" style="width:${paidPct}%"></span></div><div class="progress-labels"><span>Current value + paid</span><span>${fmt(allCost,t.decimals)} ${esc(t.currency)} entry</span></div>`}<div class="mini-stats"><div class="mini-stat"><span class="label">TOKEN VALUE · ${esc(t.currency)}</span><strong>${fmt(value,t.decimals)}</strong></div><div class="mini-stat"><span class="label">PAID · ${esc(t.currency)}</span><strong>${fmt(p.paid,t.decimals)}</strong></div><div class="mini-stat"><span class="label">FUNDED UNPAID</span><strong>${fmt(p.funded-p.paid,t.decimals)}</strong></div></div><div class="kv"><span>Remaining eligible shortfall</span><strong>${fmt(s.shortfall,t.decimals)} ${esc(t.currency)}</strong></div><div class="kv"><span>Next-round estimate</span><strong>${waiting?'Hidden · round pending':fmt(estimate,t.decimals)+' '+esc(t.currency)}</strong></div>${showAction?`<button class="btn dark full mt" data-action="claim" data-id="${esc(t.id)}">Claim available demo rewards ↗</button>`:''}`;}
function chart(t){const data=[];let y=155;for(let i=0;i<=60;i++){y=Math.max(30,Math.min(160,y-1.7+Math.sin(i*3.21)*7.2));data.push([i*9.3+3,y]);}const line='M'+data.map(p=>p.join(',')).join(' L');return `<svg class="big-chart" viewBox="0 0 620 205" preserveAspectRatio="none" aria-label="Illustrative price chart, not a market feed"><defs><linearGradient id="chart-fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#527bff" stop-opacity=".5"/><stop offset="1" stop-color="#162644" stop-opacity="0"/></linearGradient></defs>${[35,75,115,155].map(y=>`<path d="M0 ${y}H566" stroke="#28344a" stroke-dasharray="3 5" stroke-width=".8"/>`).join('')}<path d="${line} L561,180 L3,180 Z" fill="url(#chart-fill)"/><path d="${line}" fill="none" stroke="#789cff" stroke-width="2"/><circle cx="${data.at(-1)[0]}" cy="${data.at(-1)[1]}" r="3" fill="#789cff"/><text x="578" y="38">HIGH</text><text x="578" y="157">LOW</text><text x="5" y="202">00:00</text><text x="143" y="202">06:00</text><text x="284" y="202">12:00</text><text x="425" y="202">18:00</text><text x="546" y="202">24:00</text></svg>`;}
function tradeCard(t){const p=pos(t),qty=p?p.lots.reduce((s,l)=>s+l.quantity,0n)+p.unrecognized:0n;return `<aside class="trade-card"><div class="card-title"><h3>Trade ${esc(t.symbol)}</h3><span class="tag warning">DEMO ONLY</span></div><div class="tabs"><button data-side="buy" class="${tradeSide==='buy'?'active':''}">Buy</button><button data-side="sell" class="${tradeSide==='sell'?'active':''}">Sell</button></div><div class="amount-box"><label for="trade-amount"><span>You ${tradeSide==='buy'?'pay':'sell'}</span><span>Demo balance ${tradeSide==='buy'?fmt(state.demoBalances[t.currency],t.decimals):fmt(qty,6,2)}</span></label><div class="amount-input"><input id="trade-amount" inputmode="decimal" placeholder="0.00" autocomplete="off"><b>${esc(tradeSide==='buy'?t.currency:t.symbol)}</b></div></div><div class="quick-amounts">${(tradeSide==='buy'?['0.1','0.5','1','5']:['100','1000','5000','10000']).map(x=>`<button data-amount="${x}">${x}</button>`).join('')}</div><div class="kv"><span>Estimated receive</span><strong id="trade-receive">-</strong></div>${taxLabels(t)}<div class="kv"><span>Slippage / curve impact</span><strong>Not modeled</strong></div>${tradeSide==='sell'?'<div class="notice danger mt">Selling permanently ends eligibility for future recovery rounds.</div>':''}<button class="btn dark full" data-action="trade">Simulate ${tradeSide==='buy'?'buy':'sell'} ↗</button><p class="trade-note">Fixed-price demonstration, not a bonding-curve quote. No signing or fund movement. Gross cost is used as demo entry basis.</p><div class="error" id="trade-error" role="alert"></div></aside>`;}
function rounds(t){return `<section class="card"><div class="card-title"><h3>Reward rounds</h3><span class="tag neutral">LOCAL LEDGER</span></div><div class="table-container" style="border:0"><table class="receipt-table"><thead><tr><th>Round</th><th>Funded</th><th>Recipients</th><th>Status</th><th>Evidence</th></tr></thead><tbody>${[...t.treasury.rounds].reverse().map(r=>`<tr><td>#${r.id.toString().padStart(3,'0')}</td><td>${fmt(r.amount,t.decimals)} ${esc(t.currency)}</td><td>${r.allocations.length}</td><td><span class="tag ${r.cancelled?'warning':'lime'}">${r.cancelled?'CANCELLED':state.now<r.claimableAt?'10 MIN WAIT':r.allocations.every(a=>a.paid)?'DEMO PAID':'CLAIMABLE'}</span></td><td><button class="text-button" data-round="${r.id}" data-id="${esc(t.id)}">Manifest ↗</button></td></tr>`).join('')||'<tr><td colspan="5">No funded rounds yet.</td></tr>'}</tbody></table></div><div class="round-actions"><span class="muted" style="font-size:9px">Manifest inclusion is not proof of correct loss calculation.</span><button class="btn outline small" data-action="fund" data-id="${esc(t.id)}">Fund demo round ↗</button></div></section>`;}
function tokenPage(){const t=currentToken();const p=pos(t);return `<a href="#explore" class="back">← All tokens</a><div class="token-head"><div class="token-head-left">${icon(t,true)}<div><h1>${esc(t.name)}</h1><p>$${esc(t.symbol)} <span>·</span> ${esc(t.currency)} rewards <span class="tag-inline">Comeback mode</span></p></div></div><div class="pill-group"><span class="tag neutral">NO ON-CHAIN MINT</span><button class="btn outline small" data-action="copy-token">Copy demo link ↗</button></div></div>${liveNotice()}<div class="token-layout"><section class="chart-card"><div class="chart-top"><div><span class="muted">Illustrative market cap</span><div class="chart-value">${money(t.marketCap||0)}</div><span class="${t.change>=0?'positive':'negative'}" style="font-size:11px">${t.change>=0?'+':''}${(t.change||0).toFixed(2)}% <span class="muted">sample · past 24h</span></span></div><span class="tag neutral">NOT A PRICE FEED</span></div>${chart(t)}<div class="chart-foot"><span>ILLUSTRATIVE CHART</span><span>Ledger quote: ${fmt(t.priceQ*1000000n/E.PRICE_SCALE,t.decimals,9)} ${esc(t.currency)} / token</span></div></section>${tradeCard(t)}</div><div class="section-tabs"><button data-detail-tab="overview" class="${detailTab==='overview'?'active':''}">Overview</button><button data-detail-tab="rewards" class="${detailTab==='rewards'?'active':''}">Rewards & evidence</button><button data-detail-tab="trades" class="${detailTab==='trades'?'active':''}">Demo trades</button></div>${detailTab==='trades'?tradeHistory(t):detailTab==='rewards'?rounds(t):`<div class="token-detail-grid"><section class="card">${p?positionSummary(t,p):'<h3>No demo position yet.</h3><p class="muted mt">Make a simulated buy to explore the 15-minute eligibility timer.</p>'}<div class="scenario"><label class="field"><span>Recovery scenario <small>reference price vs. base quote</small></span><input id="scenario-price" type="range" min="20" max="160" value="${Number(t.priceQ*100n/(unit(t)*E.PRICE_SCALE/10000n/1000000n))}" aria-label="Simulated reference price percentage"></label><p>The slider models this price across a complete 15-minute window. It does not change the illustrative market chart.</p></div><div class="controls-row"><button class="btn outline small" data-action="advance-15">Advance demo 15 min →</button>${p?`<button class="btn outline small" data-action="outgoing" data-id="${esc(t.id)}">Test outgoing transfer ↗</button>`:''}</div></section><section class="card"><div class="card-title"><h3>Token treasury</h3><span class="tag neutral">SIMULATED</span></div><div class="recovery-value">${fmt(t.treasury.available,t.decimals)}<small>${esc(t.currency)}</small></div><p class="muted" style="font-size:10px;margin:8px 0 14px">Available for future holder rounds</p><div class="kv"><span>Reserved for funded awards</span><strong>${fmt(t.treasury.reserved,t.decimals)} ${esc(t.currency)}</strong></div><div class="kv"><span>Completed demo payouts</span><strong>${fmt(t.treasury.paid,t.decimals)} ${esc(t.currency)}</strong></div><div class="kv"><span>Operations allocation</span><strong>${fmt(t.treasury.operations,t.decimals)} ${esc(t.currency)}</strong></div><div class="kv"><span>$RBD buyback allocation</span><strong>${fmt(t.treasury.buybacks,t.decimals)} ${esc(t.currency)}</strong></div>${feeBar()}<div class="controls-row"><button class="btn dark small" data-action="fund" data-id="${esc(t.id)}">Fund demo round ↗</button><button class="btn outline small" data-action="advance-10">Advance 10 min →</button></div><p class="muted" style="font-size:9px;margin-top:15px">New generation-4 awards wait 10 minutes before delivery. Funded awards reduce the next loss calculation immediately.</p></section></div>${rounds(t)}` }<div class="notice mt bottom-space">Demo positions use a local accounting model, not verified Solana activity. Live trading, indexing, oracle checks, treasury custody, and payout execution are not connected.</div>`;}
function tradeHistory(t){return `<section class="card bottom-space"><div class="card-title"><h3>Simulated trades</h3><span class="tag neutral">NOT TRANSACTIONS</span></div><table class="receipt-table"><thead><tr><th>Side</th><th>Actor</th><th>Quote amount</th><th>Tokens</th></tr></thead><tbody>${[...t.trades].reverse().map(x=>`<tr><td class="${x.side==='buy'?'positive':'negative'}">${esc(x.side)}</td><td>${esc(x.wallet)}</td><td>${fmt(x.amount,t.decimals)} ${esc(t.currency)}</td><td>${fmt(x.quantity,6,2)}</td></tr>`).join('')||'<tr><td colspan="4">No local trades yet.</td></tr>'}</tbody></table></section>`;}
function portfolio(){const held=state.tokens.filter(t=>pos(t));return `<div class="page-head"><div><div class="eyebrow">YOUR DEMO PORTFOLIO</div><h1>Your portfolio</h1><p>Recognized entry, token value, funded awards, and completed payments.</p></div><button class="btn outline" data-action="advance-15">Advance demo 15 min →</button></div>${liveNotice()}<div class="notice mb">These are positions for the fictional <b>demo-holder</b>. No wallet balance or portfolio is fetched from Solana. Paper funds: ${fmt(state.demoBalances.SOL)} SOL.</div><div class="portfolio-list">${held.map(t=>`<section class="card portfolio-item"><div class="portfolio-item-head"><div class="token-info">${icon(t)}<div><h3>${esc(t.name)}</h3><span class="muted" style="font-size:10px">$${esc(t.symbol)} · ${esc(t.currency)} rewards</span></div></div><a href="#token/${esc(t.id)}" class="btn outline small">View token ↗</a></div><div class="portfolio-inner"><div>${positionSummary(t,pos(t),false)}</div><div><div class="notice">Each qualifying wallet receives its proportional share of available funds, capped by its eligible shortfall. Estimates are not promised payments.</div><button class="btn dark full mt" data-action="claim" data-id="${esc(t.id)}">Claim available demo rewards ↗</button></div></div></section>`).join('')||'<div class="empty">No demo positions. Explore a token to simulate a purchase.</div>'}</div>`;}
function analytics(){const sol=state.tokens.filter(t=>t.currency==='SOL');const vals=sol.map(t=>Number(t.treasury.paid)/1e9),max=Math.max(...vals,.1);return `<div class="page-head"><div><div class="eyebrow">PLATFORM ANALYTICS</div><h1>Treasury activity</h1><p>Collected fees, reserved awards, and completed SOL payouts.</p></div><span class="tag neutral">NO LIVE INDEXER</span></div>${metrics()}<div class="two-columns"><section class="card"><div class="card-title"><h3>Completed holder payments · SOL</h3><span class="tag neutral">DEMO TOTALS</span></div><div class="analytics-chart">${sol.map((t,i)=>`<div class="analytics-bar" style="height:${Math.max(5,vals[i]/max*85)}%"><span>${fmt(t.treasury.paid,9,3)} SOL</span></div>`).join('')}</div><div class="analytics-axis">${sol.map(t=>`<span>${esc(t.symbol)}</span>`).join('')}</div><p class="muted mt" style="font-size:10px">All holder payouts are denominated in SOL. Funded but unpaid awards are excluded.</p></section><section class="card"><div class="card-title"><h3>Fee destinations</h3><span class="tag lime">80 / 15 / 5</span></div><div class="kv"><span>Received net fees</span><strong>${assetTotals(totals('collected'))}</strong></div><div class="kv"><span>Unpaid funded liabilities</span><strong>${assetTotals(totals('reserved'))}</strong></div><div class="kv"><span>Operations</span><strong>${assetTotals(totals('operations'))}</strong></div><div class="kv"><span>Platform buyback reserve</span><strong>${assetTotals(totals('buybacks'))}</strong></div>${feeBar()}<div class="notice mt">Allocated is not paid. Reserved is not available. Rounding dust stays in the ledger.</div></section></div><section class="card bottom-space"><div class="card-title"><h3>Treasury accounting by token</h3><span class="tag neutral">ATOMIC-UNIT LEDGER</span></div><div class="table-container" style="border:0"><table class="receipt-table"><thead><tr><th>Token</th><th>Collected</th><th>Available</th><th>Reserved</th><th>Paid</th></tr></thead><tbody>${state.tokens.map(t=>`<tr><td><a href="#token/${esc(t.id)}">${esc(t.symbol)} ↗</a><span class="muted"> · ${esc(t.currency)}</span></td><td>${fmt(t.treasury.collected,t.decimals)}</td><td>${fmt(t.treasury.available,t.decimals)}</td><td>${fmt(t.treasury.reserved,t.decimals)}</td><td>${fmt(t.treasury.paid,t.decimals)}</td></tr>`).join('')}</tbody></table></div></section>`;}
function buybacks(){const s=E.buybackStatus(state.buyback,state.now),remaining=s.readyAt?Math.max(0,s.readyAt-state.now):0;return `<div class="page-head"><div><div class="eyebrow">THE PLATFORM TOKEN / $RBD</div><h1>$RBD buybacks</h1><p>Every launch contributes to one platform-token buyback allocation.</p></div><span class="tag warning">TOKEN NOT DEPLOYED</span></div><section class="buyback-hero"><div><span class="eyebrow">BUYBACK RESERVE</span><h2>5% of net fees.<br>Reserved for $RBD.</h2><p>5% of net collected fees enter the shared $RBD buyback reserve. Intended purchases are bounded and subject to price, liquidity, slippage, and timing checks.</p></div><div class="buyback-symbol">↗</div></section><div class="two-columns"><section class="card"><div class="card-title"><h3>Shared buyback allocation</h3><span class="tag neutral">DEMO FUNDS</span></div><div class="recovery-value" style="font-size:34px">${assetTotals(totals('buybacks'))}</div><div class="divider"></div><div class="kv"><span>On-chain platform mint</span><strong>Not deployed</strong></div><div class="kv"><span>Buyback route</span><strong>${s.reason==='not-configured'?'Not scheduled':s.ready?'Time gate passed; checks still required':'Activation waiting period'}</strong></div><div class="kv"><span>Activation wait remaining</span><strong>${s.readyAt?Math.ceil(remaining/3600000)+' demo hours':'Starts at scheduling, not page load'}</strong></div><div class="kv"><span>Completed purchases / burned</span><strong>0 / 0</strong></div><div class="controls-row"><button class="btn dark small" data-action="schedule-buyback" ${state.buyback.scheduledAt!=null?'disabled':''}>Schedule demo activation ↗</button><button class="btn outline small" data-action="advance-48" ${state.buyback.scheduledAt==null?'disabled':''}>Advance demo 48h →</button></div><p class="muted" style="font-size:10px;margin-top:16px">The 12-hour routing-correction window and 48-hour activation wait are separate. Passing a timer is not a purchase. No buyback executor is included.</p></section><section class="card"><div class="card-title"><h3>Contributions by launch</h3></div>${state.tokens.map(t=>`<div class="kv"><span>${esc(t.name)}</span><strong>${fmt(t.treasury.buybacks,t.decimals)} ${esc(t.currency)}</strong></div>`).join('')}</section></div>`;}
function docs(){return `<section class="docs"><div class="page-head"><div><div class="eyebrow">MECHANICS / BUILD STATUS</div><h1>Recovery mechanics</h1><p>Independently implemented from Uplift’s public documentation. No affiliation.</p></div></div><div class="notice warning mb">This is a working local prototype and reference ledger, not a deployed Solana protocol. No smart contract holds funds. No live trading, transfers, claims, price feeds, or buybacks occur.</div><div class="docs-grid"><article class="card"><h3>The Comeback policy</h3><p>Comeback is this brand’s display name for the loss-rebate/v1 model. Recognized purchases mature after 15 minutes. Any sale or outgoing transfer permanently disqualifies the wallet from future awards; unrecognized incoming transfers add no eligible entry basis.</p><ul class="rule-list"><li><b>01</b>Use the higher of spot price and a complete 15-minute average.</li><li><b>02</b>Subtract reference value and all prior funded awards from eligible cost.</li><li><b>03</b>Allocate available funds proportionally to remaining shortfalls.</li></ul><div class="code">pool = min(available, sum(shortfalls))<br>award = floor(pool × shortfall / sum(shortfalls))</div></article><article class="card"><h3>Fee allocation</h3><p>Only net collected creator tax and the upstream creator-fee share enter the split. Allocating 80% / 15% / 5% does not mean that 80% of all trade volume goes to holders. The creator gets no separate share of redirected fees.</p>${feeBar()}<div class="diagram"><span>Trading fees</span><i>→</i><span>Token treasury</span><i>→</i><span>Holder rounds</span></div><p class="mt">Atomic integer amounts are used throughout. Newly collected receipts are idempotent; the same receipt cannot be split twice.</p></article><article class="card"><h3>Funding and claims</h3><p>Generation-4 rounds reserve funds immediately, then wait 10 minutes. The guardian can cancel an incorrect round during that wait. A later sale does not erase an already-funded claim. Pending awards reduce loss calculations but are excluded from received-recovery visuals.</p><div class="notice mt">Round manifests record allocations in the local ledger. They do not verify prices or on-chain activity.</div></article><article class="card"><h3>Solana settlement</h3><p>The intended port uses program-controlled treasuries, a verified trading adapter, owner-level indexing, checked price snapshots, and reward-round proofs. A generic Token-2022 transfer fee is not equivalent to a buy/sell-only venue fee.</p><p class="mt">Trading, treasury accounting, and rewards use SOL with nine decimal places. USDC is a reference asset only; stablecoin trading, conversion, and payouts are not enabled. Pump.fun integration is not connected in this prototype.</p></article><article class="card"><h3>What is implemented here?</h3><p>Token discovery, a three-step local launch wizard, illustrative buy/sell interactions, a persistent demo portfolio, deterministic recovery calculations, fee accounting, cooling periods, claims, manifests, analytics, and buyback scheduling gates.</p><p class="mt">Phantom and injected Solflare connections request an address only. Real account balances are not fetched. Mock wallet tests are not a substitute for extension testing.</p></article><article class="card"><h3>What still needs engineering?</h3><p>The Solana treasury and launch programs, curve and graduation integration, production indexer, manipulation-resistant pricing, automatic payments, guardian operations, authenticated API writes, and a bounded buyback executor.</p><p class="mt">Exact bonding-curve economics, upstream creator-share deductions, and private buyback scheduling were not established from the inspected documentation. The demo must not be described as verified full protocol parity.</p></article></div><div class="card mt"><h3>Reference and trust model</h3><p>This build uses original artwork and source code. It does not import Uplift funds, assets, users, or on-chain contracts. REBOUND and $RBD are working names, not cleared trademarks or deployed tokens.</p><p class="mt">The production publisher is a trust assumption: public proofs establish allocation inclusion, not that a loss was measured correctly. A launch should disclose upgrade, repair, publisher, guardian, and reserve-administration powers.</p><div class="controls-row"><a class="source-link" href="https://uplift.cash/docs" target="_blank" rel="noopener noreferrer">Uplift mechanics ↗</a><a class="source-link" href="https://uplift.cash/developers" target="_blank" rel="noopener noreferrer">Uplift API definitions ↗</a><a class="source-link" href="https://solana.com/docs/core/pda" target="_blank" rel="noopener noreferrer">Solana program-controlled accounts ↗</a></div></div></section>`;}
function render(){const parts=location.hash.slice(1).split('/');route=parts[0]||'explore';tokenId=parts[1]||tokenId;const pages={explore,launch:launchPage,portfolio,analytics,buybacks,docs,token:tokenPage};if(!pages[route])route='explore';$('#main').innerHTML=pages[route]();$$('[data-nav]').forEach(a=>{const active=a.dataset.nav===(route==='token'?'explore':route);a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});document.body.dataset.route=route;const labels={explore:'Discover',token:'Token overview',launch:'Launch a token',portfolio:'Portfolio',analytics:'Analytics',buybacks:'$RBD buybacks',docs:'Documentation'};$('#route-label').textContent=labels[route];updateWalletButton();document.title=(route==='token'?currentToken().name+' · ':route==='explore'?'':route.charAt(0).toUpperCase()+route.slice(1)+' · ')+'REBOUND';}
function modal(html){$('#dialog-body').innerHTML='<div class="dialog-content">'+html+'</div>';if(!$('#dialog').open)$('#dialog').showModal();}
function closeDialog(){$('#dialog').close();}
function head(title){return `<div class="dialog-head"><h2>${esc(title)}</h2><button class="close" data-action="close" aria-label="Close dialog">×</button></div>`;}
function updateWalletButton(){const b=$('.wallet-button');b.innerHTML=connectedAddress?esc(connectedAddress.slice(0,4)+'…'+connectedAddress.slice(-4))+' <span>↗</span>':uiIcon('wallet')+'Connect wallet';}
function walletModal(){if(connectedAddress){modal(head('Wallet connected')+`<p>This is an address-only connection. It is separate from your demo portfolio. No signature is requested and nothing can be sent by this build.</p><div class="code">${esc(connectedAddress)}</div><button class="btn dark full mt" data-action="disconnect">Disconnect wallet</button>`);return;}const ph=!!window.phantom?.solana, sf=!!window.solflare;modal(head('Connect your wallet')+`<p>Connect a Solana wallet to share your public address. This prototype does not ask for signatures or send transactions.</p><button class="wallet-option" data-wallet="phantom"><span>◎</span><b>Phantom</b><small>${ph?'Detected':'Not detected'}</small></button><button class="wallet-option" data-wallet="solflare"><span style="background:#34241b;color:#e3b477">☼</span><b>Solflare</b><small>${sf?'Detected':'Not detected'}</small></button><div class="notice mt">No wallet is needed for the demo. Demo funds and rewards are fictional and never represent your connected account.</div><p class="wallet-help">Wallet extensions may not inject into a file preview. Run <b>npm start</b> from the source package and open localhost for extension access.</p><button class="btn outline full" data-action="close">Continue without a wallet →</button>`);}
function detach(){for(const [event,fn]of providerListeners)provider?.removeListener?.(event,fn);providerListeners=[];}
async function connectWallet(which){if(walletBusy)return;const candidate=which==='phantom'?window.phantom?.solana:window.solflare;if(!candidate){toast(`${which==='phantom'?'Phantom':'Solflare'} was not detected. Open the app on localhost in a browser with that wallet installed.`,true);return;}walletBusy=true;try{const result=await candidate.connect();const address=(result?.publicKey||candidate.publicKey)?.toString();if(!address||!/^[1-9A-HJ-NP-Za-km-z]{32,44}$/.test(address))throw Error('Wallet did not return a valid Solana public address.');detach();provider=candidate;connectedAddress=address;const disconnected=()=>{detach();provider=null;connectedAddress=null;render();};const changed=key=>{connectedAddress=key?.toString()||null;render();};if(provider.on){provider.on('disconnect',disconnected);provider.on('accountChanged',changed);providerListeners=[['disconnect',disconnected],['accountChanged',changed]];}closeDialog();render();toast('Wallet connected read-only. Demo balances are separate.');}catch(err){toast(err?.code===4001?'Wallet connection was declined. No changes were made.':err.message||'Could not connect wallet.',true);}finally{walletBusy=false;}}
async function disconnect(){const old=provider;detach();provider=null;connectedAddress=null;try{await old?.disconnect?.();}catch{}closeDialog();render();toast('Wallet disconnected.');}
function validateDraft(){const d=launchDraft;E.invariant(d.currency==='SOL','Rewards are paid in SOL');d.name=d.name.trim();d.symbol=d.symbol.trim().toUpperCase();E.invariant(d.name.length>=2&&d.name.length<=32,'Use a token name with 2-32 characters.');E.invariant(/^[A-Z0-9]{2,10}$/.test(d.symbol),'Ticker must have 2-10 letters or digits.');for(const key of ['website','twitter','telegram'])if(d[key]){let url;try{url=new URL(d[key]);}catch{throw Error('Enter a valid HTTPS '+key+' URL.');}E.invariant(url.protocol==='https:','Use HTTPS URLs only.');}E.validateTax(d.taxBps);}
function launchNext(){try{if(launchStep===2){const input=$('#tax-number').value;E.invariant(/^(0|[1-9]\d*)(\.\d{1,2})?$/.test(input),'Tax must have at most two decimal places.');const bps=Number(E.parseUnits(input,2));E.validateTax(bps);launchDraft.taxBps=bps;}validateDraft();if(launchStep<3){launchStep++;render();window.scrollTo(0,0);return;}E.invariant(state.tokens.length<100,'The local demo is limited to 100 tokens.');const id='demo-'+(crypto.randomUUID?crypto.randomUUID().slice(0,8):Date.now().toString(36));const t=F.token({...launchDraft,id,tone:'lime',art:'rebound',tag:'Your launch',marketCap:0,volume:0,change:0,blank:true},state.now);state.tokens.unshift(t);save();launchStep=1;launchDraft={name:'',symbol:'',description:'',website:'',twitter:'',telegram:'',currency:'SOL',taxBps:500,image:null};tradeSide='buy';detailTab='overview';go('token/'+id);toast('Demo token created. No on-chain mint or pool exists.');}catch(e){$('#launch-error').textContent=e.message;}}
function quote(t,amount,side){const tax=BigInt(t.taxBps),base=100n;if(side==='buy'){const creatorFee=amount*tax/10000n,venueFee=amount*base/10000n,net=amount-creatorFee-venueFee;return {quantity:net*E.PRICE_SCALE/t.priceQ,received:net*E.PRICE_SCALE/t.priceQ,creatorFee,venueFee};}const gross=amount*t.priceQ/E.PRICE_SCALE,creatorFee=gross*tax/10000n,venueFee=gross*base/10000n;return {quantity:amount,received:gross-creatorFee-venueFee,creatorFee,venueFee};}
function updateQuote(){const t=currentToken(),out=$('#trade-receive');if(!out)return;try{const v=$('#trade-amount').value.trim();if(!v){out.textContent='-';return;}const a=E.parseUnits(v,tradeSide==='buy'?t.decimals:6),q=quote(t,a,tradeSide);out.textContent=fmt(q.received,tradeSide==='buy'?6:t.decimals,4)+' '+(tradeSide==='buy'?t.symbol:t.currency);}catch{out.textContent='Invalid amount';}}
function simulateTrade(){const t=currentToken();try{const amount=E.parseUnits($('#trade-amount').value.trim(),tradeSide==='buy'?t.decimals:6);E.invariant(amount>0n,'Enter an amount greater than zero.');const q=quote(t,amount,tradeSide);E.invariant(q.received>0n,'Amount is too small for this demo quote.');let p=pos(t);if(tradeSide==='buy')E.invariant(amount<=state.demoBalances[t.currency],'Insufficient paper funds. Reset the demo to restore balances.');else{E.invariant(!!p,'No demo position to sell.');E.invariant(amount<=p.lots.reduce((s,l)=>s+l.quantity,0n)+p.unrecognized,'Insufficient demo tokens.');}
 const execute=()=>{try{const id='demo-trade-'+state.tokens.reduce((s,t)=>s+t.trades.length,0)+'-'+state.now;if(!p){p=E.newPosition('demo-holder');t.positions.push(p);}if(tradeSide==='buy'){state.demoBalances[t.currency]-=amount;E.purchase(p,{id,quantity:q.quantity,officialCost:amount,at:state.now});}else{E.outgoing(p,amount);state.demoBalances[t.currency]+=q.received;}E.collect(t.treasury,id,q.creatorFee,state.now);t.trades.push({id,side:tradeSide,wallet:'demo-holder',amount,quantity:q.quantity,at:state.now,simulated:true});save();closeDialog();render();toast(tradeSide==='buy'?'Demo buy recorded. This lot becomes eligible after 15 demo minutes.':'Demo sale recorded. Future eligibility is permanently ended for this demo position.');}catch(e){toast(e.message,true);}};
 if(tradeSide==='sell'){modal(head('Confirm a demo sale')+'<p>Selling disqualifies this demo wallet from future recovery rounds for this token, even after buying again. Funded claims are preserved. No real transaction occurs.</p><button id="confirm-trade" class="btn dark full">Simulate sale anyway</button>');$('#confirm-trade').onclick=execute;}else execute();
}catch(e){$('#trade-error').textContent=e.message;}}
function fundToken(id){try{const t=state.tokens.find(t=>t.id===id);const r=E.fund(t.treasury,t.positions,reference(t),state.now);save();render();toast(`Demo round #${r.id} funded: ${fmt(r.amount,t.decimals)} ${t.currency}. Advance 10 demo minutes to claim.`);}catch(e){toast(e.message,true);}}
function claimToken(id){try{const t=state.tokens.find(t=>t.id===id);let total=0n;for(const r of t.treasury.rounds){if(r.cancelled||r.claimableAt>state.now)continue;const a=r.allocations.find(a=>a.wallet==='demo-holder'&&!a.paid);if(a)total+=E.claim(t.treasury,t.positions,r.id,'demo-holder',state.now);}E.invariant(total>0n,'No matured unpaid awards. Fund a round, then advance the 10-minute demo wait.');state.demoBalances[t.currency]+=total;save();render();toast(`${fmt(total,t.decimals)} ${t.currency} added to paper funds. No blockchain transaction occurred.`);}catch(e){toast(e.message,true);}}
function advance(ms){state.now+=ms;save();render();toast(`Demo clock advanced ${ms/60000>=60?ms/3600000+' hours':ms/60000+' minutes'}. No real-world timer was changed.`);}
function plain(obj){return JSON.parse(JSON.stringify(obj,(_,x)=>typeof x==='bigint'?x.toString():x));}
async function manifest(id,roundId){const t=state.tokens.find(t=>t.id===id),r=t?.treasury.rounds.find(r=>r.id===roundId);if(!r)return;const manifest={meta:{simulated:true,chain:'solana-concept',programId:null,mint:null,evidence:'Local allocation manifest, not a chain receipt'},token:t.symbol,asset:t.currency,decimals:t.decimals,policy:E.POLICY,round:r};modal(head('Round #'+r.id+' · demo evidence')+'<p>Amounts below are integer atomic units. Transaction signatures are null because no chain payment occurred. The calculation publisher would remain a trust assumption in production.</p><pre class="manifest-pre">'+esc(JSON.stringify(plain(manifest),null,2))+'</pre><button id="download-manifest" class="btn dark full mt">Save demo manifest ↓</button>');$('#download-manifest').onclick=()=>download('rebound-'+t.symbol+'-round-'+r.id+'.json',JSON.stringify(plain(manifest),null,2),'application/json');}
function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function copyToken(){const text=location.href;try{await navigator.clipboard.writeText(text);toast('Demo link copied. Local file links are usable only on this computer.');}catch{modal(head('Your demo token link')+'<p>A local link is not a public launch URL.</p><div class="code">'+esc(text)+'</div>');}}
async function upload(file){try{E.invariant(file&&['image/png','image/jpeg','image/webp'].includes(file.type),'Choose a PNG, JPEG, or WebP image.');E.invariant(file.size<=5*1024*1024,'Image must be under 5 MB.');const bitmap=await createImageBitmap(file);E.invariant(bitmap.width>0&&bitmap.height>0,'Invalid image dimensions');const canvas=document.createElement('canvas');canvas.width=canvas.height=256;const ctx=canvas.getContext('2d'),side=Math.min(bitmap.width,bitmap.height);ctx.drawImage(bitmap,(bitmap.width-side)/2,(bitmap.height-side)/2,side,side,0,0,256,256);bitmap.close();const data=canvas.toDataURL('image/webp',.8);E.invariant(data.length<=131072,'Image is too large after resizing.');launchDraft.image=data;render();}catch(e){toast(e.message||'Unable to read image.',true);}}
const actions={menu:()=>modal(head('Explore REBOUND')+'<nav class="mobile-nav" aria-label="Mobile navigation">'+[['explore','Explore tokens'],['launch','Launch a token'],['portfolio','Your demo portfolio'],['analytics','Analytics'],['buybacks','$RBD buybacks'],['docs','Documentation']].map(([url,name])=>'<a href="#'+url+'" data-action="close">'+name+'<span>↗</span></a>').join('')+'</nav>'),wallet:walletModal,close:closeDialog,disconnect,'launch-next':launchNext,'launch-back':()=>{if(launchStep===1)go('explore');else{launchStep--;render();}},trade:simulateTrade,'advance-15':()=>advance(900000),'advance-10':()=>advance(600000),'advance-48':()=>advance(172800000),'copy-token':copyToken,'schedule-buyback':()=>{state.buyback.configuredAt=state.now;state.buyback.scheduledAt=state.now;save();render();toast('Demo schedule recorded. Activation is measured from this action, not page load.');},reset:()=>{modal(head('Reset the local demo?')+'<p>This clears your simulated tokens, trades, and reward history in this browser. It does not affect a real wallet.</p><button id="confirm-reset" class="btn dark full">Reset demo</button>');$('#confirm-reset').onclick=()=>{state=F.create();save();filter='all';search='';sort='cap';closeDialog();go('explore');render();toast('Demo reset.');};},fund:el=>fundToken(el.dataset.id),claim:el=>claimToken(el.dataset.id),outgoing:el=>{const t=state.tokens.find(t=>t.id===el.dataset.id),p=pos(t);modal(head('Test an outgoing transfer')+'<p>This removes one demo token and permanently ends future eligibility for this wallet and token. Any funded claims survive. No real tokens move.</p><button id="confirm-outgoing" class="btn dark full">Simulate outgoing transfer</button>');$('#confirm-outgoing').onclick=()=>{try{E.outgoing(p,1000000n);save();closeDialog();render();toast('Demo transfer recorded. Future payout eligibility is now permanently off.');}catch(e){toast(e.message,true);}};}};
document.addEventListener('click',e=>{const el=e.target.closest('[data-action],[data-token],[data-filter],[data-side],[data-amount],[data-round],[data-wallet],[data-currency],[data-detail-tab]');if(!el)return;try{if(el.dataset.action){actions[el.dataset.action]?.(el);return;}if(el.dataset.token){tradeSide='buy';detailTab='overview';go('token/'+el.dataset.token);}else if(el.dataset.filter){filter=el.dataset.filter;render();}else if(el.dataset.side){tradeSide=el.dataset.side;render();}else if(el.dataset.amount){$('#trade-amount').value=el.dataset.amount;updateQuote();}else if(el.dataset.round){manifest(el.dataset.id,Number(el.dataset.round));}else if(el.dataset.wallet){connectWallet(el.dataset.wallet);}else if(el.dataset.currency){E.invariant(el.dataset.currency==='SOL','Rewards are paid in SOL');launchDraft.currency='SOL';render();}else if(el.dataset.detailTab){detailTab=el.dataset.detailTab;render();}}catch(err){toast(err.message,true);}});
document.addEventListener('input',e=>{const el=e.target;if(el.id==='search'){search=el.value;$('#market-rows').innerHTML=marketRows();}if(el.id==='trade-amount')updateQuote();if(el.dataset.draft){launchDraft[el.dataset.draft]=el.value;const name=$('.preview-name'),sub=$('.preview-sub');if(name)name.textContent=launchDraft.name||'Token name';if(sub)sub.textContent='$'+(launchDraft.symbol.toUpperCase()||'TOKEN')+' · '+launchDraft.currency+' rewards';}if(el.id==='tax-range'){launchDraft.taxBps=Number(el.value);$('#tax-number').value=launchDraft.taxBps/100;const prev=$('.sticky');if(prev)prev.outerHTML=launchPreview();}if(el.id==='tax-number'){const n=Number(el.value),bps=Math.round(n*100);if(Number.isFinite(n)&&bps>=10&&bps<=1000&&Math.abs(n*100-bps)<1e-7){launchDraft.taxBps=bps;$('#tax-range').value=bps;$('.sticky').outerHTML=launchPreview();$('#launch-error').textContent='';}else{$('#launch-error').textContent='Tax must be 0.10%-10.00%, with at most two decimals.';}}});
document.addEventListener('change',e=>{if(e.target.id==='sort'){sort=e.target.value;$('#market-rows').innerHTML=marketRows();}if(e.target.id==='image-input')upload(e.target.files[0]);if(e.target.id==='scenario-price'){const t=currentToken();t.priceQ=(unit(t)*E.PRICE_SCALE/10000n/1000000n)*BigInt(e.target.value)/100n;save();render();}});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!e.ctrlKey&&!e.metaKey&&!e.altKey&&!/^(INPUT|TEXTAREA|SELECT)$/.test(e.target.tagName)&&!e.target.isContentEditable&&!$('#dialog').open&&$('#search')){e.preventDefault();$('#search').focus();return;}if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-token]')){e.preventDefault();go('token/'+e.target.dataset.token);}});
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog'))closeDialog();});
window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:'instant'});});
Object.defineProperty(window,'ReboundDemo',{value:Object.freeze({inspect:()=>E.parse(E.stringify(state)),quote,version:'0.3.0'}),writable:false});
render();
})();
